		t.Fatalf("write project settings: %v", err)
	}
	if err := os.WriteFile(filepath.Join(entireDir, "settings.local.json"),
		[]byte(`{"log_level":"debug"}`), 0o644); err != nil {
		t.Fatalf("write local settings: %v", err)
	}
